let chooser_0 = { let q: &dyn Query = g; Some(asker.controller).expect("a reference that always names a player") }; let spell_0: Option<ObjectId> = { let q: &dyn Query = g; t_0_raw.get(0).copied().and_then(|t: Target| t.object()) }; let mut open_0: Vec<ObjectId> = { let q: &dyn Query = g; q.state().battlefield().iter().copied().filter(|&id| (!(t_0_raw.get(0).copied().and_then(|t: Target| t.object()).and_then(|spell: ObjectId| { let state = q.state(); let item = state.stack.iter().find(|i| i.kind == StackKind::Spell && i.object == spell).or_else(|| state.left_stack(spell))?; let mut chosen = state.targets(item).iter(); let first = chosen.next()?.object()?; match chosen.any(|t| t.object() != Some(first)) { true => None, false => Some(first) } }) == Some(id)) && q.chars(id).is(CardType::Creature))).collect::<Vec<ObjectId>>() }; if let Some(spell) = spell_0 { while !open_0.is_empty() { let to = match open_0.as_slice() { [one] => Some(*one), _ => cantrip_mechanics::choose::card(g, chooser_0, asker.source, Purpose::Choose, open_0.clone())? }; let Some(to) = to else { break; }; open_0.retain(|&o| o != to); g.change_a_target_to(Target::Object(spell), to, chooser_0)?; let changed = { let q: &dyn Query = g; q.state().stack.iter().find(|i| i.kind == StackKind::Spell && i.object == spell).is_some_and(|i| q.state().targets(i).contains(&Target::Object(to))) }; if changed { break; } } }
